import numpy as np
from scipy.spatial.transform import Rotation

def rot(axis,a):
    return Rotation.from_rotvec(np.asarray(axis)*a).as_matrix()
def attitude(p,yaw=0):
    roll=np.arctan2(-p[42],-p[43]); pitch=np.arcsin(p[41])
    return Rotation.from_euler('ZYX',[yaw,pitch,roll]).as_matrix()
def foot(q,side):
    i=side*5; s=1 if side==0 else -1
    v=np.array([0.,s*.087,-.174]); R=rot([0,0,1],q[i])
    v+=R@np.array([.039,0,0]); R=R@rot([1,0,0],q[i+1])
    v+=R@np.array([0,s*.116,0]); R=R@rot([0,1,0],q[i+2])
    v+=R@np.array([0,0,-.4]); R=R@rot([0,1,0],q[i+3])
    v+=R@np.array([0,0,-.4]); R=R@rot([0,1,0],q[i+4])
    return v+R@np.array([.04,0,-.065])
def feet(p):
    R=attitude(p)
    return np.array([R@foot(p[:19],i) for i in range(2)])
def legik(x,y,z,side,pitch=.04):
    s=1 if side==0 else -1
    pos=rot([0,1,0],-pitch)@np.array([x,y,z])-np.array([.039,s*.087,-.174])
    x,y,z=pos
    b=s*.116; d=np.sqrt(y*y+z*z)
    roll=np.arctan2(y,-z)-np.arcsin(b/d)
    L=np.sqrt(d*d-b*b)
    knee=2*np.arccos(np.clip(np.sqrt(x*x+L*L)/.8,0,1))
    hip=np.arctan2(-x,L)-knee/2
    ankle=-pitch-hip-knee
    return np.array([0,roll,hip,knee,ankle])
if __name__=='__main__':
 import json
 from pathlib import Path
 for st in [0,10,15,25,35]:
  fn=Path('/app/output/initial/meta.json') if st==0 else Path(f'/app/output/log/{st:04d}/meta.json')
  p=np.array(json.loads(fn.read_text())['proprio']['now']); f=feet(p)
  print(st,'feet',np.round(f,3),'base',np.round(-f.mean(axis=0),3))
 for shift in [0,.05,.1,.15]:
